// #Sireum

package drone_lifecycle_governor.Drone_Lifecycle_Governor

import org.sireum._
import art._
import drone_lifecycle_governor._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait FlightReadinessOwner_Api {
  def id: Art.BridgeId
  def navigationCondition_Id : Art.PortId
  def radioCondition_Id : Art.PortId
  def flightQualification_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var flightQualification: Drone_Lifecycle_Governor.FlightQualification.Type = $

  def put_flightQualification(value : Drone_Lifecycle_Governor.FlightQualification.Type) : Unit = {
    Contract(
      Modifies(flightQualification),
      Ensures(
        flightQualification == value
      )
    )
    Spec {
      flightQualification = value
    }

    Art.putValue(flightQualification_Id, Drone_Lifecycle_Governor.FlightQualification_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class FlightReadinessOwner_Initialization_Api (
  val id: Art.BridgeId,
  val navigationCondition_Id : Art.PortId,
  val radioCondition_Id : Art.PortId,
  val flightQualification_Id : Art.PortId) extends FlightReadinessOwner_Api

@datatype class FlightReadinessOwner_Operational_Api (
  val id: Art.BridgeId,
  val navigationCondition_Id : Art.PortId,
  val radioCondition_Id : Art.PortId,
  val flightQualification_Id : Art.PortId) extends FlightReadinessOwner_Api {

  // Logika spec var representing port state for incoming data port
  @spec var navigationCondition: Drone_Lifecycle_Governor.NavigationCondition.Type = $

  def get_navigationCondition() : Option[Drone_Lifecycle_Governor.NavigationCondition.Type] = {
    Contract(
      Ensures(
        Res == Some(navigationCondition)
      )
    )
    val value : Option[Drone_Lifecycle_Governor.NavigationCondition.Type] = Art.getValue(navigationCondition_Id) match {
      case Some(Drone_Lifecycle_Governor.NavigationCondition_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port navigationCondition.  Expecting 'Drone_Lifecycle_Governor.NavigationCondition_Payload' but received ${v}")
        None[Drone_Lifecycle_Governor.NavigationCondition.Type]()
      case _ => None[Drone_Lifecycle_Governor.NavigationCondition.Type]()
    }
    return value
  }

  // Logika spec var representing port state for incoming data port
  @spec var radioCondition: Drone_Lifecycle_Governor.RadioCondition.Type = $

  def get_radioCondition() : Option[Drone_Lifecycle_Governor.RadioCondition.Type] = {
    Contract(
      Ensures(
        Res == Some(radioCondition)
      )
    )
    val value : Option[Drone_Lifecycle_Governor.RadioCondition.Type] = Art.getValue(radioCondition_Id) match {
      case Some(Drone_Lifecycle_Governor.RadioCondition_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port radioCondition.  Expecting 'Drone_Lifecycle_Governor.RadioCondition_Payload' but received ${v}")
        None[Drone_Lifecycle_Governor.RadioCondition.Type]()
      case _ => None[Drone_Lifecycle_Governor.RadioCondition.Type]()
    }
    return value
  }
}
